import { mapState, mapMutations } from "vuex";
import { workLabel, workMomentSave, workClientCount } from "@/api/work";
import uploadPictures from "@/components/uploadPictures";
import department from "@/components/department/index.vue";
import userLabel from "@/components/labelList";
import Setting from "@/setting";
import util from "@/libs/util";
import { uploadByPieces } from "@/utils/upload";
export default {
  data() {
    return {
      formItem: {
        name: "",
        type: "0",
        client_tag_list: [],
        client_type: "0",
        user_ids: [],
        welcome_words: {
          text: {
            content: "",
          },
          attachments: [],
        },
        // images:[],
        send_type: "0",
        send_time: "", //定时发送
      },
      descType: "0",
      modalPic: false,
      picTit: "",
      tableIndex: 0,
      isChoice: "",
      //   labelList: [],
      ruleValidate: {
        name: [{ required: true, message: "名称不能为空", trigger: "blur" }],
        send_time: [
          { required: true, message: "发送时间不能为空", trigger: "change" },
        ],
      },
      gridPic: {
        xl: 6,
        lg: 8,
        md: 12,
        sm: 12,
        xs: 12,
      },
      gridBtn: {
        xl: 4,
        lg: 8,
        md: 8,
        sm: 8,
        xs: 8,
      },
      linkObj: {
        msgtype: "link",
        link: {
          media_id: "",
          title: "",
          url: "",
        },
      },
      videoObj: {
        msgtype: "video",
        video: {
          media_id: "",
          url: "",
        },
      },
      activeDepartment: {},
      isSite: true,
      onlyDepartment: false,
      openType: "",
      userList: [],
      fileUrl2: Setting.apiBaseURL + "/file/video_upload",
      uploadData: {}, // 上传参数
      header: {},
      progress: 0,
      upload_type: true,
      clientCount: 0,
      labelShow: false,
      dataLabel: [],
    };
  },
  components: {
    uploadPictures,
    department,
    userLabel,
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    labelWidth() {
      return this.isMobile ? undefined : 96;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
  },
  watch: {
    "formItem.client_tag_list"(val, oldVal) {
      if (val !== oldVal) {
        this.getClientCount();
      }
    },
    "formItem.user_ids"(val, oldVal) {
      if (val !== oldVal) {
        this.getClientCount();
      }
    },
    dataLabel(val) {
      this.formItem.client_tag_list = val.map((item) => item.id);
    },
  },
  mounted() {
    this.setCopyrightShow({ value: false });
    // this.getWorkLabel();
    this.getToken();
    this.getClientCount();
  },
  destroyed() {
    this.setCopyrightShow({ value: true });
  },
  methods: {
    ...mapMutations("admin/layout", ["setCopyrightShow"]),
    delVideo() {
      this.videoObj.video.url = "";
      this.upload_type = true;
    },
    //获取客户标签
    getWorkLabel() {
      workLabel().then((res) => {
        this.labelList = res.data.map((org) => this.mapTree(org));
      });
    },
    mapTree(org) {
      const haveChildren =
        Array.isArray(org.children) && org.children.length > 0;
      return {
        //分别将我们查询出来的值做出改变他的key
        title: org.label,
        expand: true,
        value: org.value,
        selected: false,
        checked: false,
        children: haveChildren ? org.children.map((i) => this.mapTree(i)) : [],
      };
    },
    // 点击商品图
    modalPicTap(tit, picTit, index) {
      this.modalPic = true;
      this.isChoice = tit === "dan" ? "单选" : "多选";
      this.picTit = picTit;
      this.tableIndex = index;
    },
    snedChangeTime(val) {
      this.formItem.send_time = val;
    },
    handleRemove(i) {
      this.formItem.welcome_words.attachments.splice(i, 1);
    },
    // 获取多张图信息
    getPicD(pc) {
      let images = [];
      images = pc.map((item) => {
        return item.att_dir;
      });
      images.forEach((item) => {
        let imageObj = {
          msgtype: "image",
          image: {
            media_id: "",
            pic_url: "",
          },
        };
        imageObj.image.pic_url = item;
        this.formItem.welcome_words.attachments.push(imageObj);
      });
      this.modalPic = false;
    },
    addUser() {
      this.userList = this.formItem.user_ids;
      this.$refs.department.memberStatus = true;
    },
    changeMastart(arr, type) {
      this.formItem.user_ids = arr.map((item) => {
        return {
          userid: item.userid,
          name: item.name,
          id: item.id,
        };
      });
    },
    //tag标签删除成员
    handleDel(id) {
      let index = this.formItem.user_ids.findIndex(function (val) {
        return val.id === id;
      });
      this.formItem.user_ids.splice(index, 1);
      this.getClientCount();
    },
    linkBlur() {
      if (!this.linkObj.link.url) return this.$Message.warning("请输入链接");
    },
    titleBlur() {
      if (!this.linkObj.link.title)
        return this.$Message.warning("请输入链接标题");
    },
    submit() {
      let formItem = JSON.parse(JSON.stringify(this.formItem));
      if (!formItem.welcome_words.text.content.length)
        return this.$Message.error("请填写消息内容1");
      if (this.descType == 2) {
        formItem.welcome_words.attachments.push(this.linkObj);
      } else if (this.descType == 1) {
        formItem.welcome_words.attachments.push(this.videoObj);
      }
      let formData = this.deepClone(formItem);
      formData.user_ids = formData.user_ids.map((item) => {
        return item.userid;
      });
      if (formData.client_type === "0") {
        formData.client_tag_list = [];
      }
      this.$refs.formItem.validate((valid) => {
        if (valid) {
          workMomentSave(formData)
            .then((res) => {
              this.$Message.success(res.msg);
              this.$router.push("/admin/work/client/moment");
            })
            .catch((err) => {
              this.$Message.error(err.msg);
            });
        }
      });
    },
    //深克隆
    deepClone(obj) {
      let newObj = Array.isArray(obj) ? [] : {};
      if (obj && typeof obj === "object") {
        for (let key in obj) {
          if (obj.hasOwnProperty(key)) {
            newObj[key] =
              obj && typeof obj[key] === "object"
                ? this.deepClone(obj[key])
                : obj[key];
          }
        }
      }
      return newObj;
    },
    videoSaveToUrl(file) {
      let imgTypeArr = ["video/mp4"];
      let imgType = imgTypeArr.indexOf(file.type) !== -1;
      if (!imgType) {
        return this.$Message.warning({
          content: "文件  " + file.name + "  格式不正确, 请选择格式正确的视频",
          duration: 5,
        });
      }
      uploadByPieces({
        randoms: "", // 随机数，这里作为给后端处理分片的标识 根据项目看情况 是否要加
        file: file, // 视频实体
        pieceSize: 3, // 分片大小
        success: (data) => {
          this.upload_type = false;
          this.videoObj.video.url = data.file_path;
          this.$Spin.hide();
        },
        error: (e) => {
          this.$Message.error(e.msg);
          this.$Spin.hide();
        },
        uploading: (chunk, allChunk) => {
          this.$Spin.show();
        },
      });
      return false;
    },

    // 上传头部token
    getToken() {
      this.header["Authori-zation"] = "Bearer " + util.cookies.get("token");
    },
    getClientCount() {
      workClientCount({
        is_all: this.formItem.client_type == 1 ? 0 : 1,
        label: this.formItem.client_tag_list,
        userid: this.formItem.user_ids.map((item) => {
          return item.userid;
        }),
      }).then((res) => {
        this.clientCount = res.data.sum_count;
      });
    },
    openLabel() {
      this.labelShow = true;
      this.$refs.userLabel.userLabel(
        JSON.parse(JSON.stringify(this.dataLabel))
      );
    },
    activeData(dataLabel) {
      this.labelShow = false;
      this.dataLabel = dataLabel;
    },
    // 标签弹窗关闭
    labelClose() {
      this.labelShow = false;
    },
    closeLabel(label) {
      let index = this.dataLabel.indexOf(
        this.dataLabel.filter((d) => d.id == label.id)[0]
      );
      this.dataLabel.splice(index, 1);
    },
  },
};
